  ?zone a brick:Zone ;
        rdfs:label "DataCenter_bot_ZN_6" .

  ?temp_sensor brick:isPointOf ?zone ;
               a brick:Zone_Air_Temperature_Sensor .

  ?heat_setpoint brick:isPointOf ?zone ;
                 a brick:Zone_Air_Temperature_Setpoint_Limit .
  # We might need to distinguish heating and cooling setpoints. 
  # Let's check if they have specific types or labels.
}

SELECT ?zone ?point ?point_type WHERE {
  ?zone a brick:Zone ;
        rdfs:label "DataCenter_bot_ZN_6" .
  ?point brick:isPointOf ?zone .
  ?point a ?point_type .
}

SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(?label, "DataCenter_bot_ZN_6"))
}

