import csv

# Strip the prefix for matching
temp_id = "a6b53f83-d378-5a08-b723-6834fcbf5b60"
heat_id = "0cede4f2-cbcf-5fe8-9f4b-e6428317da44"
cool_id = "93d84ff6-9ef2-55af-89d2-e5a6dcfc33b0"
target_date = "2018-01-14"

data = {}

with open(VALUES_CSV, 'r') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        ts_id, timestamp, value = row
        if timestamp.startswith(target_date):
            if timestamp not in data:
                data[timestamp] = {}
            if ts_id == temp_id:
                data[timestamp]['temp'] = float(value)
            elif ts_id == heat_id:
                data[timestamp]['heat'] = float(value)
            elif ts_id == cool_id:
                data[timestamp]['cool'] = float(value)

all_within = True
timestamps_processed = 0
sorted_timestamps = sorted(data.keys())

for ts in sorted_timestamps:
    vals = data[ts]
    if 'temp' in vals and 'heat' in vals and 'cool' in vals:
        timestamps_processed += 1
        temp = vals['temp']
        heat = vals['heat']
        cool = vals['cool']
        if not (heat <= temp <= cool):
            all_within = False
            print(f"Out of range at {ts}: temp={temp}, heat={heat}, cool={cool}")
    else:
        print(f"Missing data at {ts}: {vals}")

print(f"Processed {timestamps_processed} timestamps.")
print(f"All within: {all_within}")
